// Take the best ELIGIBLE candidate. An agent covering only some of the skills is not a cheaper
// option, it is a different job — so stop rather than quietly downgrade what was asked for.
const need = $('What you need').first().json;
const res = $json;
const ok = (res.candidates ?? []).filter((c) => c.eligible === true);
if (!ok.length) {
  const near = (res.candidates ?? [])[0];
  const s = res.searched ?? {};
  throw new Error(near
    ? `No agent covers every skill. Closest: ${near.card?.name ?? near.card?.id}, ${near.why}.`
    : `No agent publishes these skills. ${s.cards ?? 0} cards were readable; ${s.unreadable ?? 0} more agents published a card that could not be fetched.`);
}
const card = ok[0].card;
// card.id names the agent in its registry (chain:agentId). It cannot be paid. The OWNER can.
if (!card.owner) throw new Error(`${card.name ?? card.id} matched, but its owner address is unknown, so it cannot be named as a seller.`);
return [{ json: { ...need, seller: card.owner, sellerName: card.name, agent: card.id, kind: card.kind, endpoint: card.endpoint } }];
